localHarnesses.lifecycleFaults:
import { _electron } from '@playwright/test';
import fs from 'node:fs/promises';
import path from 'node:path';

const mode = process.argv[2];
const backend = mode === 'context-loss' ? 'webgl' : 'webgpu';
const output = path.resolve(`.benchmark-data/shared-texture/audit-fault-${mode}.json`);
const env = { ...process.env };
delete env.ELECTRON_RUN_AS_NODE;
let app;
let log = '';
try {
  app = await _electron.launch({ args: [path.resolve('experiments/native-gpu-shared-texture/main.cjs'),
    '--benchmark', '--show', '--force_low_power_gpu', `--backend=${backend}`,
    '--duration=6000', '--warmup=500', `--output=${output}`], env });
  app.process().stdout.on('data', chunk => { log += chunk; });
  app.process().stderr.on('data', chunk => { log += chunk; });
  const exited = new Promise(resolve => app.process().once('exit', (code, signal) => resolve({ code, signal })));
  const page = await app.firstWindow();
  await page.waitForFunction(() => document.getElementById('hud')?.textContent !== 'initializing');
  await page.waitForTimeout(2500);
  if (mode === 'source-close') await app.evaluate(({ BrowserWindow }) => {
    BrowserWindow.getAllWindows().find(w => w.webContents.isOffscreen()).destroy();
  });
  if (mode === 'consumer-close') await page.close();
  if (mode === 'quit') await app.evaluate(({ app }) => app.quit()).catch(() => {});
  if (mode === 'reload') await page.reload();
  if (mode === 'stall') await page.evaluate(() => {
    const end = performance.now() + 700;
    while (performance.now() < end) {}
  });
  if (mode === 'context-loss') await page.evaluate(() => {
    document.querySelector('canvas').getContext('webgl2').getExtension('WEBGL_lose_context').loseContext();
  });
  const result = await Promise.race([exited, new Promise(resolve => setTimeout(() => resolve({ timeout: true }), 15000).unref())]);
  console.log(JSON.stringify({ mode, result, report: await fs.readFile(output, 'utf8').then(JSON.parse).catch(() => null) }));
} finally {
  await fs.writeFile(`.git/shared-texture-fault-${mode}.log`, log);
  await app?.close().catch(() => {});
}
